import {forkView,startFork,setForkPage,setForkEvidence,setForkAnswer,setForkSupport,checkFork,forkLiveRow,forkSlip,forkAnswer,forkUnreadableAnswer} from './food-fork-core.mjs';
import {foodLinkDiagram} from './food-links-art.mjs';
import {hearButton} from './play-media.mjs';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const json=x=>{try{return JSON.stringify(x,null,2);}catch{return 'This saved record cannot be displayed. Keep the original download.';}};
const btn=(label,attr,kind='secondary')=>`<button type="button" class="${kind}" ${attr}>${esc(label)}</button>`;
const label=(s,id)=>s.cards.find(c=>c.id===id)?.label||id;
const cardArt=c=>c.drawing?.version===1&&c.drawing.kind==='hoverfly-larva'&&c.id==='hoverfly-larva'?`<figure class="fork-card-art"><img src="./food-fork-hoverfly.svg" alt="${esc(c.pictureText)}"></figure>`:foodLinkDiagram({...c,text:c.passage});
const answerText=(s,a)=>!a?'No readable proposal':a.notEnough?'Not enough evidence in this slip':a.food===null&&a.eater===null?'No pair chosen':a.food===null||a.eater===null?`Partial pair: ${a.food?esc(label(s,a.food)):'choose food'} → ${a.eater?esc(label(s,a.eater)):'choose eater'}`:`${esc(label(s,a.food))} (food) → ${esc(label(s,a.eater))} (eater)`;
const positions=n=>n===4?[[90,170],[315,170],[570,78],[570,265]]:Array.from({length:n},(_,i)=>[320+240*Math.cos(2*Math.PI*i/n-Math.PI),175+125*Math.sin(2*Math.PI*i/n-Math.PI)]);
function graph(v){const s=v.root.source,pos=positions(s.cards.length),byId=new Map(s.cards.map((c,i)=>[c.id,pos[i]]));
 const lines=s.rows.map((r,i)=>{const a=forkAnswer(v.root,r.id),live=forkLiveRow(v,r);if(!a||a.notEnough||a.food===null||a.eater===null)return '';const p=byId.get(a.food),q=byId.get(a.eater);if(!p||!q)return '';const solid=live.solid,stroke=solid?'#397958':'#956323';if(p===q)return `<path d="M${p[0]+15} ${p[1]-10}q55-70 30 10" fill="none" stroke="${stroke}" stroke-width="4" ${solid?'':'stroke-dasharray="8 6"'} marker-end="url(#fork-arrow)"/>`;const dx=q[0]-p[0],dy=q[1]-p[1],distance=Math.hypot(dx,dy)||1,ux=dx/distance,uy=dy/distance;return `<path d="M${p[0]+ux*42} ${p[1]+uy*30}L${q[0]-ux*42} ${q[1]-uy*30}" fill="none" stroke="${stroke}" stroke-width="4" ${solid?'':'stroke-dasharray="8 6"'} marker-end="url(#fork-arrow)"/>`;}).join('');
 return `<section class="fork-board" aria-label="Shared ${s.cards.length}-card food-link board"><h2>Our shared food-arrow picture</h2><p class="fork-legend">${esc(s.copy.legend)}</p><svg viewBox="0 0 800 350" aria-hidden="true" focusable="false"><defs><marker id="fork-arrow" markerWidth="9" markerHeight="9" refX="8" refY="4.5" orient="auto"><path d="M1 1L8 4.5 1 8" fill="none" stroke="#355c4b" stroke-width="1.8"/></marker></defs>${lines}${s.cards.map((c,i)=>`<g><rect x="${pos[i][0]-72}" y="${pos[i][1]-31}" width="144" height="62" rx="12" fill="#f0f4e9" stroke="#397958" stroke-width="2"/><text x="${pos[i][0]}" y="${pos[i][1]+6}" text-anchor="middle" font-size="20" font-weight="700" fill="#183f39">${i+1}</text></g>`).join('')}</svg><ol class="fork-board-cards">${s.cards.map(c=>`<li><strong>${esc(c.label)}</strong> <i>${esc(c.scientificName)}</i></li>`).join('')}</ol><ul class="fork-edge-list">${s.rows.map(r=>{const a=forkAnswer(v.root,r.id),live=forkLiveRow(v,r);return `<li><strong>${esc(r.id)}:</strong> ${answerText(s,a)}. ${a?.notEnough?live.status==='current'?esc(live.displayFeedback):'No arrow drawn.':a&&a.food&&a.eater?live.solid?'Solid: supported by this displayed slip.':live.status==='recorded-only'?'Dashed: recorded earlier, unchecked here.':'Dashed: our proposed link, not established by this slip.':'No arrow drawn.'}</li>`;}).join('')}</ul><p>${esc(s.copy.limit)}</p></section>`;}
function sourceDetails(s){return `<details class="fork-source"><summary>Original cards, slips and sources kept with this board</summary><p>${esc(s.copy.legend)}</p><ul>${s.rows.map(r=>`<li><strong>${esc(r.prompt)}</strong> Initial: ${esc(r.initial.text)}${r.closer?` Closer: ${esc(r.closer.text)}`:''}</li>`).join('')}</ul><p>${esc(s.copy.studyLimit)}</p><ul>${s.credits.map(c=>`<li><a href="${esc(c.url)}" target="_blank" rel="noopener">${esc(c.title)}</a>: ${esc(c.role)}</li>`).join('')}</ul></details>`;}
function cards(s){return `<section><h2 id="fork-focus" tabindex="-1">Read the four source cards</h2><div class="fork-cards">${s.cards.map(c=>`<article><h3>${esc(c.label)}</h3><p class="tiny"><i>${esc(c.scientificName)}</i></p>${cardArt(c)}<p>${esc(c.passage)}</p>${hearButton(c.passage,`Hear about ${c.label}`)}</article>`).join('')}</div><p>These supplied pictures tell biology. The board asks what each displayed evidence slip supports.</p>${btn('Build our food-arrow picture','data-fork-page="build"','primary')}</section>`;}
function select(s,row,part,current){return `<label class="fork-select">${part==='food'?'Food on the left':'Eater on the right'}<select data-fork-answer="${esc(row.id)}" data-part="${part}"><option value=""${current===null?' selected':''}>Choose ${part}</option>${s.cards.map(c=>`<option value="${esc(c.id)}"${current===c.id?' selected':''}>${esc(c.label)}</option>`).join('')}</select></label>`;}
function build(v){const r=v.root,s=r.source;return `<section><h2 id="fork-focus" tabindex="-1">Build links from the slips shown</h2><p>${esc(s.copy.intro)}</p>${graph(v)}<div class="fork-rows">${s.rows.map(row=>{const a=forkAnswer(r,row.id),unreadable=forkUnreadableAnswer(r,row.id),slip=forkSlip(s,row,r.evidenceView),live=forkLiveRow(v,row);return `<section class="fork-row" data-fork-row="${esc(row.id)}"><h3>${esc(row.prompt)}</h3><p class="fork-slip" id="fork-slip-${esc(row.id)}" tabindex="-1"><strong>This displayed slip:</strong> ${esc(slip.text)}</p>${row.closer?`<p class="tiny">${r.evidenceView==='initial'?'This general note cannot name this exact aphid-and-hoverfly pair. The cards may tell you more.':'The closer study names this exact pair under study conditions.'}</p>`:''}${unreadable?'<p>This row has an unreadable saved proposal. Its raw value stays in Grown-up notes. Start a separate board to replace it; other rows remain open.</p>':`<div class="fork-fields">${select(s,row,'food',a?.food??null)}${select(s,row,'eater',a?.eater??null)}</div>${btn('Not enough evidence in this slip',`data-fork-unknown="${esc(row.id)}" aria-pressed="${!!a?.notEnough}"`)}${a?.notEnough?btn('Try a pair instead',`data-fork-clear="${esc(row.id)}"`):''}`}<p class="fork-row-result" id="fork-result-${esc(row.id)}" tabindex="-1">${live.status==='current'?`Current check: ${esc(live.displayFeedback)}`:live.status==='recorded-only'?'An earlier recorded result is kept, but this displayed slip does not support its current claim. Check again.':'This row is ready for a new check.'}</p></section>`;}).join('')}</div><div class="fork-evidence">${r.source.rows.some(x=>x.closer)?r.evidenceView==='initial'?btn('Read the closer study','data-fork-evidence="closer"'):btn('Compare the earlier general note','data-fork-evidence="initial"'):''}<p>Switching the slip keeps your proposal and earlier checks; it never silently changes an arrow.</p></div><p>${esc(s.copy.check)}</p>${btn('Check what these displayed slips support','data-fork-check','primary')}<p class="tiny">Latest twelve readable checks stay here. A thirteenth replaces the oldest readable check; unreadable records remain raw.</p></section>`;}
function record(v,entry){const c=entry.check,s=v.root.source;return `<article class="fork-record" tabindex="-1"><h3>Recorded check ${c.id} · ${c.evidenceView==='closer'?'Closer study':'Initial note'}</h3><p>Support: help ${c.support.helpOpened?'opened':'not recorded'}, together ${c.support.together?'reported':'not reported'}, narration ${c.support.narrationRequested?'requested':'not requested'}.</p>${entry.rows.map(row=>{const a=c.answers[row.id],o=c.outcomes[row.id],slip=forkSlip(s,row,c.evidenceView);return `<section><h4>${esc(row.prompt)}</h4><p><strong>Displayed slip then:</strong> ${esc(slip.text)}</p><p><strong>Recorded proposal:</strong> ${answerText(s,a)}.</p><p><strong>Recorded outcome:</strong> ${o.outcome===null?'unobserved':o.outcome?'marked fit':'marked nonfit'}.</p><p>${esc(o.feedback)}</p></section>`;}).join('')}${entry.rows.length<s.rows.length?'<p>Some saved row values in this check are unreadable here and remain raw in Grown-up notes.</p>':''}<p class="tiny">These are recorded responses, not a new judgment of old work or independent science learning.</p></article>`;}
function kept(v){return `<section><h2 id="fork-focus" tabindex="-1">Earlier checks and revisions</h2><p>Past checks keep the slip version, proposed arrows and feedback they recorded. A changed proposal needs a new explicit check.</p>${v.readable.length?[...v.readable].reverse().map(x=>record(v,x)).join(''):'<p>No readable check yet.</p>'}${v.unreadable.length?`<p>${v.unreadable.length} unreadable check ${v.unreadable.length===1?'slot remains':'slots remain'} unchanged in Grown-up notes and the download.</p>`:''}${btn('Revise the board','data-fork-page="build"','primary')}</section>`;}
const dialog=`<dialog class="fork-confirm"><h2>Start a separate board?</h2><p>The whole earlier board, including checks and any earlier recovery, will stay in Grown-up notes and the download. Download a separate copy first if you want one.</p>${btn('Keep this board','data-fork-cancel')}${btn('Keep earlier work and start','data-fork-confirm','primary')}</dialog>`;
export function forkPage(state){const v=forkView(state),head='<div class="food-fork-page" data-fork-root><header class="page-heading"><a class="back" href="#living">← Living Garden</a><h1>Food-link fork board</h1><p>Draw possible food-to-eater links from displayed evidence.</p></header>';
 if(v.status==='missing')return `${head}<section class="fork-sheet"><p>Four named cards and three evidence slips can form two paths through one aphid.</p>${btn('Start this board','data-fork-start','primary')}<p id="fork-status" role="status" tabindex="-1"></p></section></div>`;
 if(v.status==='recovery')return `${head}<section class="fork-sheet"><h2 id="fork-focus" tabindex="-1">An earlier board is kept</h2><p>This saved board cannot be read here. Its entire original record remains in Grown-up notes and the download. The rest of Living Garden stays open.</p><a href="#notes">Open Grown-up notes and download</a>${btn('Start a separate board','data-fork-new')}<p id="fork-status" role="status" tabindex="-1"></p>${dialog}</section></div>`;
 const r=v.root,s=r.source;return `${head}<section class="fork-sheet"><nav aria-label="Fork board pages" class="fork-tabs">${[['cards','Cards'],['build','Build'],['kept','Kept checks']].map(([id,name])=>btn(name,`data-fork-page="${id}" aria-current="${r.page===id?'page':'false'}"`,r.page===id?'primary':'secondary')).join('')}</nav><p id="fork-status" role="status" tabindex="-1"></p>${r.page==='cards'?cards(s):r.page==='build'?build(v):kept(v)}<details class="fork-help"><summary>Help if you like</summary><p>${esc(s.copy.help)}</p>${hearButton(s.copy.help,'Hear food-arrow help')}${btn('We thought together',`data-fork-together aria-pressed="${r.support.together}"`)}</details>${sourceDetails(s)}<p><a href="#living/stages">${esc(s.copy.stage)}</a></p><p><a href="#notes">Grown-up notes and download</a></p><details><summary>Start a separate board</summary><p>The whole current board stays in the download if it can fit safely.</p>${btn('Start a separate board','data-fork-new')}</details>${dialog}</section></div>`;}
export function forkNotes(state){const v=forkView(state);if(v.status==='missing')return '';const detail=v.status==='ready'?`Latest ${v.readable.length} readable checks; ${v.unreadable.length} unreadable check slots preserved. Source: ${esc(v.root.source.id)}. Support is self-reported/requested. A result is practice with supplied evidence, not field observation or independent biology understanding.`:'This board is unreadable here. Its whole original record is preserved.';return `<details class="panel"><summary>Living Garden Food-link Fork Board</summary><p>${detail}</p><pre>${esc(json(state.foodFork))}</pre></details>`;}
export function bindFork(state,{save,render,focus,canExport}={}){const host=document.querySelector('[data-fork-root]');if(!host)return;
 const fail='This action could not fit safely in your downloadable notes. Earlier work is unchanged. Download notes first or use a separate explorer.';
 const status=msg=>{const p=document.querySelector('#fork-status');if(p){p.textContent=msg;focus?.('#fork-status');}};
 const refresh=(target,msg='')=>{save?.();render?.();if(msg){const p=document.querySelector('#fork-status');if(p)p.textContent=msg;}focus?.(target);};
 const bind=(selector,fn)=>host.querySelectorAll(selector).forEach(el=>el.addEventListener('click',()=>{if(el.isConnected)fn(el);}));
 bind('[data-fork-start]',()=>startFork(state,canExport)?refresh('#fork-focus','Board started with its own source cards.'):status(fail));
 bind('[data-fork-page]',b=>setForkPage(state,b.dataset.forkPage,canExport)?refresh('#fork-focus'):status(fail));
 bind('[data-fork-evidence]',b=>setForkEvidence(state,b.dataset.forkEvidence,canExport)?refresh('#fork-slip-hoverfly','The displayed evidence changed; your proposal and recorded checks remain.'):status(fail));
 host.querySelectorAll('[data-fork-answer]').forEach(el=>el.addEventListener('change',()=>{if(!el.isConnected)return;setForkAnswer(state,el.dataset.forkAnswer,el.dataset.part,el.value||null,canExport)?refresh(`#fork-result-${el.dataset.forkAnswer}`,'Proposal changed; check the displayed slip when ready.'):status(fail);}));
 bind('[data-fork-unknown]',b=>setForkAnswer(state,b.dataset.forkUnknown,'notEnough',true,canExport)?refresh(`#fork-result-${b.dataset.forkUnknown}`,'Row left undecided from this displayed slip.'):status(fail));
 bind('[data-fork-clear]',b=>setForkAnswer(state,b.dataset.forkClear,'notEnough',false,canExport)?refresh(`#fork-result-${b.dataset.forkClear}`,'Choose a food and eater to propose a link.'):status(fail));
 bind('[data-fork-check]',()=>{const v=forkView(state),hasReadable=v.status==='ready'&&v.root.source.rows.some(row=>forkAnswer(v.root,row.id));if(checkFork(state,canExport))refresh('.fork-record','Check kept with its displayed slips and recorded feedback.');else status(!hasReadable?'Choose a pair or Not enough evidence in at least one readable row before checking.':v.root.nextCheck>=Number.MAX_SAFE_INTEGER?'Check numbers have reached the supported limit. Download notes and start a separate board.':fail);});
 bind('[data-fork-together]',()=>setForkSupport(state,'together',canExport)?refresh('[data-fork-together]','Working together recorded as support.'):status(fail));
 const help=host.querySelector('.fork-help');help?.addEventListener('toggle',()=>{if(help.isConnected&&help.open&&setForkSupport(state,'helpOpened',canExport))save?.();});
 host.querySelectorAll('[data-speak]').forEach(b=>b.addEventListener('click',()=>{if(b.isConnected&&setForkSupport(state,'narrationRequested',canExport))save?.();}));
 bind('[data-fork-new]',()=>host.querySelector('.fork-confirm')?.showModal());
 bind('[data-fork-cancel]',()=>host.querySelector('.fork-confirm')?.close());
 bind('[data-fork-confirm]',()=>{if(startFork(state,canExport,true))refresh('#fork-focus','A separate board started. The whole earlier board remains in notes.');else{host.querySelector('.fork-confirm')?.close();status(fail);}});
}
